import {TYPES,TYPE_COLORS,typeEffectiveness,effectivenessLabel,effectivenessClass} from './type-rules.js?v=0.90.52';
const chip=type=>`<span class="type-chip" style="--type-color:${TYPE_COLORS[type]}">${type}</span>`;
const options=(selected,optional=false)=>`${optional?'<option value="">None</option>':''}${TYPES.map(type=>`<option value="${type}" ${type===selected?'selected':''}>${type}</option>`).join('')}`;
export function matchupHTML(attack,defenders){const value=typeEffectiveness(attack,defenders),incoming=TYPES.map(type=>({type,value:typeEffectiveness(type,defenders)})),list=items=>items.length?items.map(item=>`${chip(item.type)} <b>${item.value}×</b>`).join(' · '):'None';return `<div class="chart-result ${effectivenessClass(value)}" role="status">${chip(attack)} → ${defenders.map(chip).join(' / ')}<strong>${effectivenessLabel(value)}</strong></div><dl class="defense-summary"><div><dt>Weak to</dt><dd>${list(incoming.filter(item=>item.value>1))}</dd></div><div><dt>Resists</dt><dd>${list(incoming.filter(item=>item.value>0&&item.value<1))}</dd></div><div><dt>Immune to</dt><dd>${list(incoming.filter(item=>item.value===0))}</dd></div></dl>`;}
export function typeChartHTML(attack='NORMAL',defenders=['NORMAL']){return `<p class="category-key"><span>✦ Physical · Attack / Defence</span><span>◎ Special · Special Attack / Special Defence</span><span>◇ Status · effects rather than direct damage</span></p><div class="chart-pickers"><label>Attacking move type<select id="chart-attack">${options(attack)}</select></label><label>Defending type<select id="chart-defender">${options(defenders[0])}</select></label><label>Second defending type<select id="chart-second">${options(defenders[1]||'',true)}</select></label></div><div id="chart-matchup">${matchupHTML(attack,defenders)}</div><p class="chart-explanation">2× / 4×: weakness. 0.5× / 0.25×: resistance. 0×: immune. Dual-type modifiers multiply; weakness and resistance can cancel. Status moves do not use damage multipliers.</p><details class="full-chart"><summary>Full 18-type chart</summary><div class="chart-scroll" tabindex="0" role="region" aria-label="Scrollable type chart"><table><caption>Rows: attacking move. Columns: defending type.</caption><thead><tr><th scope="col">Attack / Defend</th>${TYPES.map(type=>`<th scope="col">${chip(type)}</th>`).join('')}</tr></thead><tbody>${TYPES.map(attack=>`<tr><th scope="row">${chip(attack)}</th>${TYPES.map(defend=>{const value=typeEffectiveness(attack,[defend]);return `<td class="${effectivenessClass(value)}">${value}×</td>`;}).join('')}</tr>`).join('')}</tbody></table></div></details>`;}
